<?php get_header(); $term=get_queried_object(); ?><main class="section service-archive"><div class="eyebrow">НАПРАВЛЕНИЕ ПРОДВИЖЕНИЯ</div><h1><?php echo esc_html($term->name);?></h1><p class="lead"><?php echo esc_html($term->description);?></p><div class="service-grid"><?php if(have_posts()):while(have_posts()):the_post();$thumb=orh_media_url(get_the_ID(),'large');$lb=get_post_meta(get_the_ID(),'orh_service_label',true);$ac=get_post_meta(get_the_ID(),'orh_service_accent',true)?:'acid';?><a class="service-card <?php echo esc_attr($ac);?>" href="<?php the_permalink();?>"><div class="service-visual" <?php if($thumb)echo 'style="background-image:url(\''.esc_url($thumb).'\')"';?>><span><?php echo esc_html($lb?:'УСЛУГА');?></span><i>↗</i></div><div class="service-card-copy"><h3><?php the_title();?></h3><p><?php echo esc_html(get_the_excerpt());?></p><strong>Подробнее →</strong></div></a><?php endwhile;else:?><div class="empty">В этом направлении пока нет услуг.</div><?php endif;?></div></main><?php get_footer();?>